def _semantic_slots_and_clients(
    clients: list[tuple[object, str, str]],
    model1: str | None,
    model2: str | None,
    configured: list[Any] | None = None,
    trial: Any = None,
) -> tuple[list[dict[str, Any]], dict[str, object], bool]:
    """Freeze configured slots before client availability can change the matrix."""
    from tools.llm_registry import resolve_slots

    configured = resolve_slots()[:2] if configured is None else configured
    overrides = [model1 or os.environ.get("LANGCHAIN_MODEL"), model2 or model1]
    expected = [
        (slot.provider, override or slot.model)
        for slot, override in zip(configured, overrides, strict=False)
    ]
    if len(expected) != 2 or len(clients) != 2:
        raise InputCapacityError("semantic mode requires both configured native judge slots")
    slots: list[dict[str, Any]] = []
    clients_by_slot: dict[str, object] = {}
    authentic = True
    for index, ((client, _label, _model), (provider, model)) in enumerate(
        zip(clients, expected, strict=True)
    ):
        prepared = _prepare_capacity_client(client)
        contract = (
            _native_capacity_contract(prepared)
            if trial is None
            else _native_capacity_contract(prepared, trial=trial)
        )
        if contract["provider"] != provider or contract["model"] != model:
            raise InputCapacityError(
                "available native client does not match frozen configured slot"
            )
        native_sdk = (
            getattr(prepared, "root_client", None)
            if provider == "openai"
            else getattr(prepared, "_client", None)
        )
        if getattr(native_sdk, "max_retries", None) != 0:
            raise InputCapacityError("native SDK retries must be disabled at construction")
        if trial is not None:
            trial.check_sdk(native_sdk)
        slot_id = f"slot-{index + 1}"
        slots.append(
            {
                "slot_id": slot_id,
                "provider": provider,
                "model": model,
                "transport": str(contract["endpoint"]),
                "config_sha256": canonical_digest(
                    {"provider": provider, "model": model, "contract": contract}
                ),
            }
        )
        clients_by_slot[slot_id] = prepared
        authentic = authentic and contract.get("provenance") != "synthetic-unit-test-only"
    return slots, clients_by_slot, authentic

recorded_tests.test_semantic_slots_require_zero_native_:
def test_semantic_slots_require_zero_native_sdk_retries(native_slots, index, retries) -> None:
    sdk = (
        native_slots.prepared[index].root_client
        if index == 0
        else native_slots.prepared[index]._client
    )
    if retries is None:
        del sdk.max_retries
    else:
        sdk.max_retries = retries

    with pytest.raises(verifier.InputCapacityError, match="retries must be disabled"):
        verifier._semantic_slots_and_clients(
            native_slots.clients, None, None, native_slots.configured
        )

    assert native_slots.contract.call_count == index + 1

recorded_tests.test_semantic_package_prompt_retains_byt:
def test_semantic_package_prompt_retains_bytes_selected_obligations_and_chain_depth(
    monkeypatch, depth
) -> None:
    monkeypatch.setenv("CHAIN_DEPTH", str(depth))
    monkeypatch.setattr(verifier, "_load_prompt", lambda: "Context:\n{context}\nDiff:\n{diff}")
    dependency_text = "# Closed dependency\n\u00e9 = 1\n" + "source bytes\n" * 500
    prepared = {"prompts": {"review-1": {"bytes": dependency_text.encode("utf-8")}}}
    selected = {"id": "criterion-1", "text": "Preserve complete reviewed code."}
    contract = {"clauses": [selected, {"id": "criterion-2", "text": "Unassigned obligation."}]}

    prompt = verifier._semantic_package_prompt(
        prepared, {"id": "review-1", "clause_ids": ["criterion-1"]}, contract
    )

    assert dependency_text in prompt
    assert '"id": "criterion-1"' in prompt
    assert selected["text"] in prompt
    assert "criterion-2" not in prompt and "Unassigned obligation." not in prompt
    assert "Complete changed-code dependencies are included in the reviewed spans above." in prompt
    if depth:
        assert prompt.endswith(verifier.CHAIN_DEPTH_ADDENDUM.format(depth=depth))
    else:
        assert "Follow-up Iteration Context" not in prompt
